'use strict';
// Pre-rendered neural speech with original lines and designed character profiles.
// Same-origin audio: no runtime speech service, microphone or browser TTS.
const voiceClips=new Map(),powerClips=new Map(),powerChannels=new Map();let voiceUnlocked=false,voiceSerial=0,remoteAudioSeq=-1,lastAudioFrame=-1;
function playClip(name,volume=.65,rate=1){if(!sound||!voiceUnlocked)return;try{let base=voiceClips.get(name);if(!base){base=new Audio(`assets/audio/${name}.mp3`);base.preload='auto';voiceClips.set(name,base)}const clip=base.cloneNode();clip.volume=volume;clip.playbackRate=rate;clip.play().catch(()=>{})}catch{}}
function preparePowerVoices(ids){for(const [id,clips]of powerClips)if(!ids.includes(id)){for(const clip of clips){clip.pause();clip.removeAttribute('src');clip.load()}powerClips.delete(id)}for(const id of ids)if(!powerClips.has(id))powerClips.set(id,Array.from({length:4},(_,power)=>{const clip=new Audio(`assets/audio/powers/${id}-${power}.wav`);clip.preload='auto';return clip}))}
function playPowerVoice(id,power){if(!sound||!voiceUnlocked||!Number.isInteger(power)||power<0||power>3)return;preparePowerVoices(game.p.map(p=>p.id));powerChannels.get(id)?.pause();const clip=powerClips.get(id)?.[power]?.cloneNode();if(!clip)return;clip.volume=power===3?.94:.8;powerChannels.set(id,clip);clip.play().catch(()=>{});}
function playFighterVoice(id,kind){const channel=powerChannels.get(id);if(channel&&!channel.paused&&!channel.ended)return;const female=[3,4,6].includes(id),n=Math.floor(Math.random()*(female?(kind==='hurt'?7:6):12)),name=female?(kind==='hurt'?`female-hurt-${n}`:`female-attack-${n}`):`male-${n}`;const rates=[.99,1.06,.86,1.04,.94,.81,.9,.91];playClip(name,kind==='super'?.9:.48,rates[id])}
sound=true;$('#sound').textContent='SONIDO: SÍ';
document.addEventListener('pointerdown',()=>{if(voiceUnlocked)return;voiceUnlocked=true;try{audio??=new(window.AudioContext||window.webkitAudioContext)();audio.resume()}catch{}},{once:true});document.addEventListener('keydown',()=>{voiceUnlocked=true},{once:true});
$('#sound').onclick=()=>{sound=!sound;voiceUnlocked=true;$('#sound').textContent='SONIDO: '+(sound?'SÍ':'NO');if(sound)playClip('announcer-ready');else for(const clip of powerChannels.values())clip.pause()};
say=function(text){if(!sound)return;const upper=text.toUpperCase();if(roster.some(r=>r.slice(3).includes(text)))return;if(upper.includes('DALE')){const token=++voiceSerial;playClip('announcer-ready');setTimeout(()=>{if(playing&&token===voiceSerial)playClip('announcer-fight',.65)},1650)}else if(game?.done){const own=host?0:1;playClip(game.p[own].wins>=2?'announcer-you_win':'announcer-you_lose',.8)}else if(game?.wait>0){const token=voiceSerial;setTimeout(()=>{if(playing&&token===voiceSerial)playClip(`announcer-round_${Math.min(game.round,5)}`)},1600);setTimeout(()=>{if(playing&&token===voiceSerial)playClip('announcer-fight')},2950)}};
function processVoiceEvents(state){if(state.frame<lastAudioFrame)remoteAudioSeq=-1;lastAudioFrame=state.frame;const events=state.audioEvents||[state.audioCue].filter(Boolean);for(const event of events){if(event.seq<=remoteAudioSeq)continue;remoteAudioSeq=event.seq;if(Number.isInteger(event.power))playPowerVoice(event.id,event.power);else playFighterVoice(event.id,event.kind)}}
const voicedDraw=draw;draw=function(now){voicedDraw(now);if(game)processVoiceEvents(game)};
